package com.fakelegacy.customer;

import java.util.List;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class AddressDao {

    public static final int MAX_ADDRESSES = 5;

    @Autowired
    private JdbcTemplate jdbc;

    public List<Address> findByCustomer(long customerId) {
        return jdbc.query("select * from addresses where customer_id = ? order by id", (rs, i) -> {
            Address a = new Address();
            a.setId(rs.getLong("id"));
            a.setCustomerId(rs.getLong("customer_id"));
            a.setCountry(rs.getString("country"));
            a.setCity(rs.getString("city"));
            a.setLine(rs.getString("line"));
            a.setDefaultShipping(rs.getBoolean("default_shipping"));
            return a;
        }, customerId);
    }

    public void checkMax(List<Address> addresses) {
        if (addresses.size() > MAX_ADDRESSES) {
            throw new IllegalArgumentException("a customer can have at most " + MAX_ADDRESSES + " addresses");
        }
    }

    public void replaceAll(long customerId, List<Address> addresses) {
        checkMax(addresses);
        jdbc.update("delete from addresses where customer_id = ?", customerId);
        for (Address a : addresses) {
            jdbc.update("insert into addresses (customer_id, country, city, line, default_shipping) values (?,?,?,?,?)",
                    customerId, a.getCountry(), a.getCity(), a.getLine(), a.isDefaultShipping());
        }
    }
}
